def anchor(c,s,q):
 t=next(e['text'] for e in P[c]['entries'] if e['source_id']==s);start=t.index(q);return {'source_id':s,'span':{'start':start,'end':start+len(q),'quote':q}}
def affected(a,units=[],rels=[],summary=[]):return {'annotation_id':a,'unit_ids':units,'relation_ids':rels,'summary_paths':summary}
def add(fid,c,diag,effect,desc,aff,ev,rule,res):
 if not any(f['finding_id']==fid for f in review['findings']):review['findings'].append({'finding_id':fid,'episode_id':c,'diagnosis':diag,'effect':effect,'description':desc,'affected':aff,'source_evidence':[anchor(c,*x) for x in ev],'applicable_rule':rule,'resolution':res})
